def main():
    rng = random.Random("economie_toetsen_96_115_seed_1")
    assert len(EXAMENS) == 20, f"Verwacht 20 examens (96 t/m 115), gevonden: {len(EXAMENS)}"

    tot_lang, tot_kort, tot_mc_all = 0, 0, 0
    for nr in sorted(EXAMENS):
        hfd, par, titel, icoon, vr = EXAMENS[nr]
        assert len(vr) == 20, f"examen_{nr} heeft {len(vr)} vragen i.p.v. 20"
        t = [v["type"] for v in vr]
        mc_c, wow_c, inv_c, op_c = t.count("mc"), t.count("waaronwaar"), t.count("invul"), t.count("open")
        assert (mc_c, wow_c, inv_c, op_c) == (10, 5, 3, 2), f"examen_{nr} type mismatch: {mc_c, wow_c, inv_c, op_c}"
        onwaar_c = sum(1 for v in vr if v["type"] == "waaronwaar" and v["antwoord"] is False)
        assert onwaar_c >= 2, f"examen_{nr} heeft te weinig onwaar ({onwaar_c}/5)"

        vr_geplaatst = plaats([dict(v) for v in vr], rng)
        n_lang, tot_mc = langste_aandeel(vr_geplaatst)
        n_kort, _ = kortste_aandeel(vr_geplaatst)
        tot_lang += n_lang
        tot_kort += n_kort
        tot_mc_all += tot_mc
        print(f"examen_{nr:3d} (§{par}): {len(vr_geplaatst)} vragen, langste {n_lang}/{tot_mc}, kortste {n_kort}/{tot_mc}")
        assert n_lang / tot_mc <= 0.4, f"examen_{nr}: juiste optie {n_lang}/{tot_mc} keer langste (>40%)"
        assert n_kort / tot_mc <= 0.4, f"examen_{nr}: juiste optie {n_kort}/{tot_mc} keer kortste (>40%)"

        ex = {
            "id": f"ex-h3-economie-{nr}",
            "hoofdstuk": hfd,
            "paragraaf": par,
            "titel": titel,
            "vak": "Economie · HAVO 3 (Pincode)",
            "icoon": icoon,
            "duurMin": 20,
            "vragen": vr_geplaatst,
        }
        pad = os.path.join(ROOT, f"examen_{nr}.js")
        kop = (
            f"/* =========================================================\n"
            f"   Duru's Economie (HAVO 3) — {titel}\n"
            f"   ========================================================= */\n"
        )
        inhoud = kop + "DURU.registerExamen(" + json.dumps(ex, ensure_ascii=False, indent=2) + ");\n"
        with open(pad, "w", encoding="utf-8") as f:
            f.write(inhoud)

    print(f"\nTotaal MC ({tot_mc_all}): langste {tot_lang}/{tot_mc_all} ({tot_lang/tot_mc_all*100:.1f}%), "
          f"kortste {tot_kort}/{tot_mc_all} ({tot_kort/tot_mc_all*100:.1f}%).")
    print("Alle 20 examens (96-115) succesvol gegenereerd!")


if __name__ == "__main__":
    main()
